/** Observe actual PC HP publisher threads before introducing a PC target FIFO; no source queue execution claim. */
public class PlayerCommitIngressProbe extends PlayerFoeGapProbe {
 public static void main(String[] args)throws Exception{
  var config=copy(ServerConfig.load(Path.of(args[0]),"standard"),Map.of("classicWorldMonsterPoisonFixtureRoll",1,"uncannyDodgeHitFixtureD20",20,"uncannyDodgeHitFixtureD100",1,"battleNaturalHpRegenEnabled",false,"battleNaturalMpRegenEnabled",false));ResourceDatabase.load(config);var rf=CombatRegression.current(CombatRules.class);var original=(CombatRules.Snapshot)rf.get(null);var root=Path.of(args[1]);Files.createDirectories(root);var rows=new ArrayList<String>();int inline=0,cases=0;
  try(var capture=new CaptureLog(root.resolve("capture"))){for(boolean world:new boolean[]{false,true})for(String kind:List.of("physical","magic","Foe","NPC-poison-clock")){
   var state=new GameStateStore(root.resolve("unused"+cases),false,true);var accounts=new MemoryAccountRepository("fixture","fixture","",0,1,40,52);
   try(var hub=new GameHub(config,state,accounts);var f=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var p=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var m=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME);var o=new SourceLoginRegression.Fixture(config,accounts,state,capture,hub,0,ClientSession.Endpoint.GAME)){
    var clock=(ScheduledExecutorService)get(hub,"battleClock");clock.shutdownNow();check(clock.awaitTermination(1,TimeUnit.SECONDS),"clock stopped so only requested native producer executes");var fixtures=List.of(f,p,m,o);
    for(int i=0;i<4;i++){var pc=fixtures.get(i).session;NativeDirectoryRegression.init(fixtures.get(i),"CommitIngress"+cases+"_"+i,0,config.classicServerNames().get(0));var c=((List<CharacterSummary>)get(pc,"characters")).get(0);set(pc,"characters",List.of(copy(c,Map.of("objectId",0x3b200001L+cases*8+i,"type",i==0?5:0,"level",99,"intelligence",9,"originalIntelligence",9,"wisdom",9,"originalWisdom",9))));set(pc,"sourcePhysicalGrowthStats",SourcePhysicalGrowthStats.classic381());set(pc,"sourceBaseMagicResistance",new SourceBaseMagicResistance(0,0,0,0,0));set(pc,"sourceEquipmentMagicStats",SourceEquipmentMagicStats.none());}
    FlowRegression.setup(hub,f.session,p.session,m.session,o.session);var caster=f.session;var target=p.session;for(int i=0;i<2;i++){var pc=fixtures.get(i).session;set(pc,"positionX",world?33089+i:32740+i);set(pc,"positionY",world?32717:32798);if(world){set(pc,"phase",Enum.valueOf((Class)get(pc,"phase").getClass(),"WORLD"));set(pc,"classicWorldMapId",4);set(pc,"classicWorldInstanceId",-1);hub.enterClassicWorld(pc,4,33089+i,32717,0);}}
    ready(caster,1000);set(caster,"learnedSkills",Set.of(4,187));set(caster,"sourceEquipmentMagicStats",new SourceEquipmentMagicStats(copy(SourceEquipmentPhysicalStats.none(),Map.of("weapon",new SourceWeaponPhysicalStats(272,18,1,1,2,0,0,0,0),"itemMeleeDamage",3)),37,0));gear(target,0,0,0);set(target,"playerHp",4000);set(target,"playerMaxHp",5000);set(target,"playerMp",1000);rf.set(null,ClassDamageRegression.with(original,Map.of("FOE_SLAYER_DMG",1.0,"Other_To_isDragonKnight_pc",kind.equals("Foe")?0.0:1.0)));
    long poisonTick=0;if(kind.equals("NPC-poison-clock")){PoisonCallbackRegression.nativeNpc(target,PoisonCallbackRegression.OLD_NPC,1,System.nanoTime());poisonTick=(long)get((BattleTimedStatus)get(target,"timedStatus"),"poisonNextTickAtNanos");check(poisonTick>0,"actual native NPC poison installed before selected clock tick");}
    var published=new CountDownLatch(1);var publisher=new AtomicReference<String>();var stack=new AtomicReference<String>();var error=new AtomicReference<Throwable>();var afterReturn=new AtomicInteger();Socket originalSocket=(Socket)get(target,"socket");Socket watched=new Socket(){public OutputStream getOutputStream()throws IOException{return new FilterOutputStream(originalSocket.getOutputStream()){public void write(byte[] bytes,int offset,int length)throws IOException{boolean first=false;if((int)getUnchecked(target,"playerHp")<4000&&publisher.compareAndSet(null,Thread.currentThread().getName())){check(!Thread.holdsLock(hub)&&!Thread.holdsLock((BattleTimedStatus)getUnchecked(target,"timedStatus")),"observed native HP publication holds no hub/status monitor");first=true;stack.set(Arrays.stream(Thread.currentThread().getStackTrace()).filter(e->e.getClassName().startsWith("local.lito381.server.")).map(StackTraceElement::getMethodName).reduce((a,b)->a+" > "+b).orElse(""));}out.write(bytes,offset,length);if(first)published.countDown();}public void write(int value)throws IOException{out.write(value);}};}};set(target,"socket",watched);String producer="PC-native-"+(world?"WORLD":"BATTLE")+"-"+kind;final long tick=poisonTick;
    var thread=new Thread(()->{try{if(kind.equals("NPC-poison-clock"))call(target,"serverExpireTimedStatuses",new Class[]{long.class},tick);else if(kind.equals("physical"))call(caster,"handle",new Class[]{byte[].class},new Protocol.Writer().c(0x17).d(target.playerObjectId()).h((int)get(target,"positionX")).h((int)get(target,"positionY")).bytes());else call(caster,"handle",new Class[]{byte[].class},new Protocol.Writer().c(0x14).c(kind.equals("Foe")?23:0).c(kind.equals("Foe")?2:3).d(target.playerObjectId()).h((int)get(target,"positionX")).h((int)get(target,"positionY")).bytes());afterReturn.set((int)get(target,"playerHp"));}catch(Throwable e){error.set(e);}},producer);
    thread.start();thread.join(5000);if(error.get()==null)check(published.await(5,TimeUnit.SECONDS),"actual target HP publication completes before fixture closes");set(target,"socket",originalSocket);watched.close();check(!thread.isAlive()&&error.get()==null,"native producer returns without failure: "+error.get());check(publisher.get()!=null&&(int)get(target,"playerHp")<4000,"actual positive target HP and publication observed for "+kind);boolean same=producer.equals(publisher.get());if(same)inline++;rows.add("{\"world\":"+world+",\"family\":\""+kind+"\",\"producer\":\""+producer+"\",\"publisher\":\""+publisher.get()+"\",\"publisher_is_producer\":"+same+",\"HP_at_request_return\":"+afterReturn.get()+",\"native_HP_stack\":\""+stack.get()+"\"}");cases++;
   }
  }}finally{rf.set(null,original);}
  Files.writeString(Path.of(args[2]),"{\"cases\":"+cases+",\"checks\":"+checks+",\"native_producer_thread_HP_publications\":"+inline+",\"native_PC_FIFO_or_source_threading_parity_verified\":false,\"rows\":["+String.join(",",rows)+"]}\n");System.out.println("PASS native PC ingress observations checks="+checks+"; cases="+cases+"; producer-thread HP publications="+inline+"; physical/magic/Foe actual packets and real NPC-poison clock; PC target FIFO pending");
 }
 static Object getUnchecked(Object o,String n){try{return get(o,n);}catch(Exception e){throw new AssertionError(e);}}
}
